from __future__ import annotations

from typing import Any

from schema import ChargeResult


def summarize_result(result: ChargeResult) -> dict[str, Any]:
    payload = result.normalized_payload
    return {
        "invoice_id": payload.get("invoice_id", ""),
        "account_id": payload.get("account_id", ""),
        "ok": result.ok,
        "reason": result.reason,
        "total_cents": result.total_cents,
        "requires_manual_review": result.requires_manual_review,
        "status": payload.get("status", ""),
        "currency": payload.get("currency", ""),
    }


def classify_event(result: ChargeResult) -> str:
    if not result.ok:
        return "reject"
    if result.requires_manual_review:
        return "review"
    return "accept"


def build_audit_line(result: ChargeResult) -> str:
    summary = summarize_result(result)
    return (
        f"invoice={summary['invoice_id']} "
        f"account={summary['account_id']} "
        f"event={classify_event(result)} "
        f"reason={summary['reason']} "
        f"total_cents={summary['total_cents']} "
        f"status={summary['status']} "
        f"currency={summary['currency']}"
    )


def summarize_batch_for_alerting(results: list[ChargeResult]) -> dict[str, int]:
    accepted = 0
    rejected = 0
    reviewed = 0

    for result in results:
        event = classify_event(result)
        if event == "accept":
            accepted += 1
        elif event == "reject":
            rejected += 1
        else:
            reviewed += 1

    total = accepted + rejected + reviewed
    return {
        "total": total,
        "accepted": accepted,
        "rejected": rejected,
        "reviewed": reviewed,
    }


def should_page_oncall(stats: dict[str, int]) -> bool:
    total = stats.get("total", 0)
    rejected = stats.get("rejected", 0)
    reviewed = stats.get("reviewed", 0)
    if total <= 0:
        return False
    if rejected >= 10:
        return True
    if total >= 20 and reviewed / total > 0.50:
        return True
    return False


def safe_join_lines(lines: list[str]) -> str:
    return "\n".join(line.strip() for line in lines if line.strip())


def build_report(results: list[ChargeResult]) -> str:
    lines = [build_audit_line(result) for result in results]
    stats = summarize_batch_for_alerting(results)
    lines.append(
        "batch_summary "
        f"total={stats['total']} accepted={stats['accepted']} "
        f"rejected={stats['rejected']} reviewed={stats['reviewed']} "
        f"page_oncall={should_page_oncall(stats)}"
    )
    return safe_join_lines(lines)

