from __future__ import annotations

from typing import Any

from coercion import normalize_payload
from schema import ChargeInput, ChargeResult, build_result, empty_result, to_public_payload


REVIEW_REASONS = {
    "high_retry_count",
    "failed_status",
    "suspicious_metadata_flag",
}


def _compute_total(amount_cents: int, tax_rate: float) -> int:
    taxed = amount_cents + int(round(amount_cents * tax_rate))
    return taxed


def _needs_manual_review(charge: ChargeInput) -> tuple[bool, list[str]]:
    reasons: list[str] = []
    if charge.retry_count >= 3:
        reasons.append("high_retry_count")
    if charge.status == "failed":
        reasons.append("failed_status")
    risk_flag = str(charge.metadata.get("risk_flag", "")).strip().lower()
    if risk_flag in {"manual", "high", "fraud-review"}:
        reasons.append("suspicious_metadata_flag")
    return (len(reasons) > 0, reasons)


def process_charge(raw_payload: dict[str, Any]) -> ChargeResult:
    try:
        charge = normalize_payload(raw_payload)
    except ValueError as exc:
        return empty_result(f"invalid_payload:{exc}")

    requires_review, reasons = _needs_manual_review(charge)
    total = _compute_total(charge.amount_cents, charge.tax_rate)

    if total < 0:
        return empty_result("invalid_total")

    if charge.status == "paid" and charge.retry_count > 0:
        # Historical contract: paid after retries should still be accepted,
        # but marked for audit visibility.
        requires_review = True
        reasons.append("paid_after_retry")

    if charge.currency == "EUR" and charge.auto_capture and charge.status == "failed":
        # Partner integration safety: never auto-capture failed EUR charges.
        return build_result(
            ok=False,
            reason="euro_failed_autocapture_blocked",
            total_cents=total,
            requires_manual_review=True,
            normalized_payload=to_public_payload(charge),
        )

    reason = "accepted"
    if requires_review:
        reason = "accepted_with_review:" + ",".join(sorted(set(reasons)))

    return build_result(
        ok=True,
        reason=reason,
        total_cents=total,
        requires_manual_review=requires_review,
        normalized_payload=to_public_payload(charge),
    )


def process_batch(payloads: list[dict[str, Any]]) -> dict[str, int | list[ChargeResult]]:
    results: list[ChargeResult] = []
    accepted = 0
    rejected = 0
    for payload in payloads:
        result = process_charge(payload)
        results.append(result)
        if result.ok:
            accepted += 1
        else:
            rejected += 1
    return {
        "accepted": accepted,
        "rejected": rejected,
        "results": results,
    }

