from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any


ALLOWED_CURRENCIES = {"USD", "AUD", "EUR", "GBP"}
ALLOWED_STATUSES = {"pending", "paid", "failed"}


@dataclass(frozen=True)
class ChargeInput:
    invoice_id: str
    account_id: str
    amount_cents: int
    tax_rate: float
    retry_count: int
    auto_capture: bool
    currency: str = "USD"
    status: str = "pending"
    metadata: dict[str, Any] = field(default_factory=dict)

    def validate(self) -> None:
        if not self.invoice_id.strip():
            raise ValueError("invoice_id is required")
        if not self.account_id.strip():
            raise ValueError("account_id is required")
        if self.amount_cents < 0:
            raise ValueError("amount_cents must be >= 0")
        if not (0.0 <= self.tax_rate <= 1.0):
            raise ValueError("tax_rate must be between 0 and 1")
        if self.retry_count < 0:
            raise ValueError("retry_count must be >= 0")
        if self.currency not in ALLOWED_CURRENCIES:
            raise ValueError("currency not supported")
        if self.status not in ALLOWED_STATUSES:
            raise ValueError("status not supported")


@dataclass(frozen=True)
class ChargeResult:
    ok: bool
    reason: str
    total_cents: int
    requires_manual_review: bool
    normalized_payload: dict[str, Any]


def to_public_payload(data: ChargeInput) -> dict[str, Any]:
    return {
        "invoice_id": data.invoice_id,
        "account_id": data.account_id,
        "amount_cents": data.amount_cents,
        "tax_rate": data.tax_rate,
        "retry_count": data.retry_count,
        "auto_capture": data.auto_capture,
        "currency": data.currency,
        "status": data.status,
        "metadata": data.metadata,
    }


def build_result(
    *,
    ok: bool,
    reason: str,
    total_cents: int,
    requires_manual_review: bool,
    normalized_payload: dict[str, Any],
) -> ChargeResult:
    return ChargeResult(
        ok=ok,
        reason=reason,
        total_cents=total_cents,
        requires_manual_review=requires_manual_review,
        normalized_payload=normalized_payload,
    )


def empty_result(reason: str) -> ChargeResult:
    return ChargeResult(
        ok=False,
        reason=reason,
        total_cents=0,
        requires_manual_review=False,
        normalized_payload={},
    )

